{"file_path": "store.py", "content": """"A tiny key-value store backed by a module-level dictionary.

Public functions carry the ``st_`` prefix.
"""

_data = {}


def st_get(k):
    """API: Return the value stored under key *k* (or None if missing)."""
    return _data.get(k)


def st_set(k, v):
    """API: Store value *v* under key *k*, returning *v*."""
    _data[k] = v
    return v


def st_drop(k):
    """API: Drop key *k* if present, returning its value, else None."""
    return _data.pop(k, None)


def st_scan(prefix):
    """API: Return a list of keys starting with *prefix*."""
    return [k for k in _data if k.startswith(prefix)]
